          objectiveContext,
          actorSide: request?.actorSide,
          objectiveCompactMode: request?.objectiveCompactMode,
          terminalProjectionMode,
          routeMechanicalSignature,
          utilityMechanicalSignature,
          terminalWorldDependencyHash,
          terminalCallOrigin,
          distribution,
