            mergeCalls: 0,
            totalInputBranches: 0,
            totalOutputBranches: 0,
            maxInputBranches: 0,
            maxOutputBranches: 0,
            deferredMergeCalls: 0,
            deferredMergeBranches: 0,
            deferredMergeMaxBranches: 0,
