          if (amounts.ruleBlocks > 0) preview.consumeRuleBlockCharges(next, scale * amounts.ruleBlocks);
          if (amounts.deathSaves > 0) preview.consumeDeathSaveCharges(next, scale * amounts.deathSaves);
